def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start value. sorted() creates a new list, ensuring input is not mutated.
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = []

    for current in sorted_intervals:
        # If merged is empty or there is no overlap/touching
        if not merged or current[0] > merged[-1][1]:
            # Append a copy of the current interval to prevent mutation of input lists
            merged.append(list(current))
        else:
            # Overlap or touching detected: Merge by updating the end of the last interval
            merged[-1][1] = max(merged[-1][1], current[1])

    return merged

import heapq

def toposort(nodes, edges):
    # Initialize adjacency list and in-degree counter
    adj = {node: [] for node in nodes}
    indeg = {node: 0 for node in nodes}

    # Build graph and validate edges
    for src, dst in edges:
        if src == dst:
            raise ValueError("Cycle detected: self loop")
        adj[src].append(dst)
        indeg[dst] += 1

    # Initialize min-heap with nodes having zero in-degree
    heap = [node for node in nodes if indeg[node] == 0]
    heapq.heapify(heap)

    result = []

    while heap:
        u = heapq.heappop(heap)
        result.append(u)

        # Process neighbors
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)

    # Check for cycles
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError

    result = []
    current_batch = []
    current_sum = 0

    for name, weight in items:
        if weight <= 0:
            raise ValueError
        if weight > limit:
            raise ValueError

        if current_sum + weight <= limit:
            current_batch.append(name)
            current_sum += weight
        else:
            result.append(current_batch)
            current_batch = [name]
            current_sum = weight

    if current_batch:
        result.append(current_batch)

    return result

def parse_sse(chunks):
    result = []
    current_lines = []
    buffer = bytearray()

    for chunk in chunks:
        buffer.extend(chunk)

        while True:
            pos = buffer.find(b'\n')
            if pos == -1:
                break

            if pos > 0 and buffer[pos - 1] == ord(b'\r'):
                line_bytes = buffer[:pos - 1]
                buffer = buffer[pos + 1:]
            else:
                line_bytes = buffer[:pos]
                buffer = buffer[pos + 1:]

            try:
                line = line_bytes.decode('utf-8').rstrip('\r')
            except UnicodeDecodeError:
                continue

            stripped = line.strip()

            if not stripped:
                if current_lines:
                    event_str = '\n'.join(current_lines)
                    if event_str == '[DONE]':
                        return result
                    result.append(event_str)
                    current_lines = []
                continue

            if stripped.startswith(':'):
                continue

            if stripped.startswith('data:'):
                val = stripped[5:]
                if val and val[0] == ' ':
                    val = val[1:]
                current_lines.append(val)

    return result
